import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.BwSLX4ak.js";const p=JSON.parse('{"title":"AllMusic music sources","description":"","frontmatter":{},"headers":[],"relativePath":"en/allmusic/index.md","filePath":"en/allmusic/index.md"}'),o={name:"en/allmusic/index.md"};function r(l,e,c,n,u,d){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="allmusic-music-sources" tabindex="-1">AllMusic music sources <a class="header-anchor" href="#allmusic-music-sources" aria-label="Permalink to &quot;AllMusic music sources&quot;">​</a></h1><p>QQMusic and Kugou provide music source APIs for AllMusic. AllMusic handles player commands, the playback queue, and client communication. Sources handle search, song information, playback URLs, covers, and lyrics.</p><table tabindex="0"><thead><tr><th>Source</th><th>API ID</th><th>Source code</th><th>Download</th></tr></thead><tbody><tr><td>QQ Music</td><td><code>qqmusic</code></td><td><a href="https://github.com/hutuyee/AllMusic_QQMusic" target="_blank" rel="noreferrer">AllMusic_QQMusic</a></td><td><a href="https://github.com/hutuyee/AllMusic_QQMusic/releases" target="_blank" rel="noreferrer">Releases</a></td></tr><tr><td>Kugou</td><td><code>kugou</code></td><td><a href="https://github.com/hutuyee/AllMusic_Kugou" target="_blank" rel="noreferrer">AllMusic_Kugou</a></td><td><a href="https://github.com/hutuyee/AllMusic_Kugou/releases" target="_blank" rel="noreferrer">Releases</a></td></tr></tbody></table><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Install <a href="https://github.com/Coloryr/AllMusic" target="_blank" rel="noreferrer">AllMusic server software</a> for your platform and the matching client mod for players who want to listen.</li><li>Start once to generate AllMusic&#39;s data directory.</li><li>Stop the server or proxy and put the source JAR in <strong><code>api/</code> inside the AllMusic data directory</strong>. A common upstream path is <code>allmusic/api/</code>; use the actual generated directory and platform logs. These sources are not standalone Bukkit plugins.</li><li>Start again and confirm that AllMusic recognizes <code>qqmusic</code> or <code>kugou</code>.</li><li>Search with an explicit API ID, for example <code>/music search qqmusic 晴天</code> or <code>/music search kugou 晴天</code>.</li></ol><p>Both sources can load together. <code>defaultApi</code> chooses which source is used when its ID is omitted. Change this entry in AllMusic&#39;s <code>config.json</code> while preserving the other settings:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultApi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;qqmusic&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use <code>&quot;kugou&quot;</code> for Kugou. Restart normally after adding or replacing a source JAR. For configuration-only changes, use the reload procedure supported by your AllMusic version.</p><h2 id="version-compatibility" tabindex="-1">Version compatibility <a class="header-anchor" href="#version-compatibility" aria-label="Permalink to &quot;Version compatibility&quot;">​</a></h2><p>These extensions depend on AllMusic&#39;s <code>IMusicApi</code> interface and core objects and target Java 8 bytecode. Actual runtime requirements also depend on AllMusic, the server, and the proxy. For <code>NoSuchMethodError</code> or <code>ClassNotFoundException</code>, match the AllMusic core version used by the extension or rebuild against your core.</p><p>The <a href="./qqmusic.html">QQMusic</a> and <a href="./kugou.html">Kugou</a> guides cover song identifiers, cookies, and builds. For livestream chat requests, also install <a href="./../bilimusicbridge/">BiliMusicBridge</a> on the same platform.</p>`,11)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
